package blockbranch.realistic;
import java.util.*;
public final class TemperateDeepOceanCheck {
 public static void main(String[]args){for(long seed:new long[]{424242,1,-17}){var d=new DrainageNetwork(new TerrainShape(seed),seed);var c=new ClimateField(seed);int broad=0,retained=0;int[] codes=new int[13];for(int z=-1900000;z<=1900000;z+=16000)for(int x=-1900000;x<=1900000;x+=16000){boolean selected=TemperateDeepOcean.contains(x,z,d,c);if(!DeepOcean.contains(x,z,d)){require(!selected,"Never lake,river,land or shelf");continue;}if(selected)broad++;else retained++;var s=DeepOcean.site(d,x,z);int code=DeepOcean.cover(seed,x,z,true,s);require(code==5||code==6||code==8||code==9,"Aphotic mineral palette only");codes[code]++;if(selected)require(s.depth()>200&&TemperateOcean.climate(c.sample(x,z,d::sample)),"Confirmed marine depth and regional thermal class");}
 require(broad>1000&&retained>1000,"Substantial retained basin partition");var p=blockbranch.realistic.TemperateDeepOceanFixtures.fixture(d,seed);var s=DeepOcean.site(d,p.x(),p.z());require(s.depth()>=2000&&s.depth()<=6500&&s.slope()<=.04,"Real deep sedimented floor");var edge=blockbranch.realistic.TemperateDeepOceanFixtures.transition(d,seed);require(MarineShelf.site(d,edge.insideX(),edge.insideZ()).depth()<=200&&DeepOcean.site(d,edge.outsideX(),edge.outsideZ()).depth()>200,"Actual adjacent shelf/deep threshold");for(int z=Math.min(edge.insideZ(),edge.outsideZ())-4;z<=Math.max(edge.insideZ(),edge.outsideZ())+4;z++)for(int x=Math.min(edge.insideX(),edge.outsideX())-4;x<=Math.max(edge.insideX(),edge.outsideX())+4;x++)require(TemperateOcean.kelpHeight(seed,x,z,d,c)==0,"No vegetation at the shelf/deep transition");
 System.out.println("TEMPERATE_DEEP_OCEAN seed="+seed+" broad="+broad+" retainedBasin="+retained+" point="+p+" depth="+s.depth()+" codes="+Arrays.toString(codes)+" boundary="+edge);}
 System.out.println("TEMPERATE_DEEP_IDENTITY_REUSED_APHOTIC_BED_BOUNDARY_PASS");}
 static void require(boolean b,String m){if(!b)throw new AssertionError(m);}
}
